@'
import assert from "node:assert/strict";
import fs from "node:fs";
import { createHash } from "node:crypto";
const base = ".daoyan-agent/runs/secretary-formal-pilot-agent-intent-2026-09-24-13-development-9/main-one-time-play-evidence";
const calls = JSON.parse(fs.readFileSync(base + "/browser-calls.json", "utf8"));
const provenance = JSON.parse(fs.readFileSync(base + "/provenance.json", "utf8"));
const records = JSON.parse(fs.readFileSync(base + "/server-and-tree-records.json", "utf8"));
const hash = p => createHash("sha256").update(fs.readFileSync(p)).digest("hex");
assert.equal(calls.length, 41);
assert.equal(provenance.browserRecordCount, calls.length);
assert.equal(new Set(calls.map(c => c.callId)).size, 41);
const images = calls.flatMap(c => c.images);
assert.equal(images.length, 2);
for (const img of images) assert.equal(hash(base + "/" + img.path), img.sha256);
for (const draft of provenance.recoveryDrafts.filter(d => /^(test|e2e)\//.test(d.path))) assert.equal(hash(draft.path), draft.expected);
assert.ok(records.some(r => r.command === "npm run desktop" && r.stdout.includes("http://localhost:5173/")));
assert.equal(records.find(r => r.command === "npm run desktop").exitCode, 1);
const text = calls.map(c => c.text.join("\n")).join("\n");
for (const fact of ["原读收据 15", "原读收据 14", "原读收据 19", "本人已付 32 M", "本人已付 26 M", "本人已付 44 M", "读权已撤销", "空结果收据已提交", "POST 失证", "容量 sufficient", "容量 queueFull", "容量 capacityUnknown", "0613fc3d8e2415272f6baac5672e0081d414552ce1da9b24cb10bd713cd8ae81"]) assert.ok(text.includes(fact), fact);
const width = calls.find(c => c.callId === "call_6XELShBE6Sui3ohb0RIlKOCf");
assert.ok(width.code.includes("logs({levels:['error','warn'],limit:25})"));
assert.ok(width.text.join("\n").endsWith("[]"));
console.log(JSON.stringify({callCount:calls.length,imageCount:images.length,imageHashesVerified:true,testDraftsMatch:true,serverExitCode:1,artifacts:Object.fromEntries(["README.md","browser-calls.json","provenance.json","server-and-tree-records.json",...images.map(i=>i.path)].map(p=>[p,hash(base+"/"+p)]))},null,2));
'@ | node --input-type=module

@'
import assert from "node:assert/strict";
import fs from "node:fs";
import { resolve, dirname } from "node:path";
const file = "docs/versions/pilot-agent-intent-2026-09-24/player-implementation.md";
const doc = fs.readFileSync(file,"utf8");
let links = 0;
for (const [,url] of doc.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)) {
  if (/^(https?:|#)/.test(url)) continue;
  assert.ok(fs.existsSync(resolve(dirname(file),url.split("#")[0])), url);
  links++;
}
const pkg = JSON.parse(fs.readFileSync("package.json","utf8"));
for (const [,name] of doc.matchAll(/npm run ([a-zA-Z0-9:_-]+)/g)) assert.ok(pkg.scripts[name], name);
const task = JSON.parse(fs.readFileSync("docs/versions/pilot-agent-intent-2026-09-24/tasks/development-dev-player-a3.json","utf8"));
const calls = JSON.parse(fs.readFileSync(task.oneTimePlayAdoption.evidence.find(p=>p.endsWith("/browser-calls.json")),"utf8"));
assert.equal(task.taskId,"dev-player-a3");
assert.equal(task.status,"passed");
assert.equal(task.completed,true);
for (const s of task.oneTimePlayAdoption.scenarios) for (const r of s.records) {
  assert.equal(calls[r.number-1].callId,r.callId);
  assert.equal(calls[r.number-1].timestamp,r.timestamp);
}
assert.equal(task.oneTimePlayAdoption.sourceServerRecord.exitCode,1);
assert.equal(task.oneTimePlayAdoption.remainingRequiredEvidence.length,0);
assert.equal(task.committed,false);
assert.equal(task.pushed,false);
console.log("Player evidence links and scripts valid: "+links+" links; 19 scenario references match public call IDs/times; source server exit 1 retained; no commit/push claimed.");
'@ | node --input-type=module
